if not PTLW_IDX then PTLW_IDX = {} end
PTLW_LOADED = nil

function PTLW_LoadScripts()
	if PTLW_LOADED then return end
	local seen = {}
	local k = 1
	while PTLW_ROWS[k] do
		local s = PTLW_ROWS[k][7]
		if not seen[s] then
			ReLoadScript(s)
			seen[s] = 1
		end
		k = k + 1
	end
	PTLW_LOADED = 1
end

function PTLW_Ensure()
	local n = 0
	local k = 1
	while PTLW_ROWS[k] do
		local r = PTLW_ROWS[k]
		local ni = PTLW_IDX[k]
		if not (ni and ni > 0 and GetNpcName(ni) == r[6]) then
			local sw = SubWorldID2Idx(r[1])
			if sw and sw >= 0 then
				ni = AddNpc(r[2], r[3], sw, r[4], r[5], 0)
				if ni and ni > 0 then
					SetNpcName(ni, r[6])
					SetNpcScript(ni, r[7])
					PTLW_IDX[k] = ni
					n = n + 1
				end
			end
		end
		k = k + 1
	end
	return n
end

function PTLW_Count()
	local n = 0
	local k = 1
	while PTLW_ROWS[k] do
		local ni = PTLW_IDX[k]
		if ni and ni > 0 and GetNpcName(ni) == PTLW_ROWS[k][6] then n = n + 1 end
		k = k + 1
	end
	return n
end

function PTEXT_luawave_Tick()
	PTLW_LoadScripts()
	local n = PTLW_Ensure()
	if n > 0 and PTAdm_Log then PTAdm_Log("luawave", "OK", "npc spawned " .. n .. ", alive " .. PTLW_Count() .. "/" .. PTLW_RN) end
	PTLB_PEND = nil
	PTHT_PENDS = nil
end
